/**
 * Website Presets configure infrastructure only. No sample pages, framework
 * scaffolds, installers or source files are generated by site creation.
 */
export type Preset = {
 id:string;label:string;description:string;webServers:string[];
 versions:string[];runtime:string|null;root:string;
 available:boolean;reason?:string;initialContent:"empty";
};
export const websitePresets:ReadonlyArray<Preset>=[
 {id:"static",label:"Static HTML / CSS / JavaScript",description:"Empty website ready for manual file upload or Code Studio.",webServers:["nginx"],versions:[],runtime:null,root:"public",available:true,initialContent:"empty"},
 {id:"files",label:"File workspace",description:"Private isolated file storage without a public site.",webServers:["none"],versions:[],runtime:null,root:"public",available:true,initialContent:"empty"},
 {id:"php",label:"PHP website",description:"PHP-FPM pool with per-site identity and optional database.",webServers:["nginx","apache","openlitespeed","litespeed"],versions:["8.3","8.4","8.5"],runtime:"PHP",root:"public",available:false,reason:"Per-site PHP-FPM pools, secure server adapters and rollback verification are not yet implemented.",initialContent:"empty"},
 {id:"node",label:"Node.js application",description:"Isolated Node.js service with managed port and reverse proxy.",webServers:["nginx","apache","openlitespeed","litespeed"],versions:["22","24"],runtime:"Node.js",root:"app",available:false,reason:"Pinned Node runtime, process supervision and proxy isolation are not yet implemented.",initialContent:"empty"},
 {id:"python",label:"Python application",description:"Isolated Python ASGI/WSGI service with managed process.",webServers:["nginx","apache"],versions:["3.12","3.13"],runtime:"Python",root:"app",available:false,reason:"Per-site virtual environments and managed process isolation require further QA.",initialContent:"empty"},
 {id:"container",label:"Containerized application",description:"Docker or OCI workloads with isolated ingress.",webServers:["nginx","apache"],versions:[],runtime:"Docker",root:"app",available:false,reason:"Per-site container orchestration, quotas and network isolation are not yet implemented.",initialContent:"empty"}
];
export function getWebsitePresets(){
 return {presets:websitePresets,defaultPreset:"static",initialContent:"empty",deployableTypes:["static","files"],
  notes:"Infrastructure presets only. No website content is generated. Runtime installation must be implemented and host-tested before other choices can be deployed."};
}
export function resolvePreset(value:unknown,server:unknown,version:unknown){
 const preset=websitePresets.find(p=>p.id===value);
 if(!preset)throw Error("unsupported_site_type");
 if(typeof server!=="string"||!preset.webServers.includes(server))throw Error("unsupported_web_server");
 if(preset.versions.length === 0 ? version !== undefined && version !== null && version !== "" : typeof version !== "string" || !preset.versions.includes(version))throw Error("unsupported_runtime_version");
 if(!preset.available)throw Error("runtime_not_available");
 return {siteType:preset.id as "static"|"files",webServer:server as "nginx"|"none"};
}
